function appendModularSkyscraper(structures, cfg) {
  const {
    idPrefix,
    district,
    x: x2,
    z: z2,
    baseHalfWidth,
    podiumHeight,
    totalHeight,
    ledgeInterval,
    coreMaterial,
    podiumMaterial,
    trimColor
  } = cfg;
  structures.push({
    id: `${idPrefix}_podium`,
    center: { x: x2, y: podiumHeight * 0.5, z: z2 },
    halfExtents: { x: baseHalfWidth + 3, y: podiumHeight * 0.5, z: baseHalfWidth + 3 },
    material: podiumMaterial,
    emissiveTrim: trimColor,
    district
  });
  const midSplitY = podiumHeight + (totalHeight - podiumHeight) * 0.55;
  const lowerShaftH = midSplitY - podiumHeight;
  structures.push({
    id: `${idPrefix}_lower_shaft`,
    center: { x: x2, y: podiumHeight + lowerShaftH * 0.5, z: z2 },
    halfExtents: { x: baseHalfWidth, y: lowerShaftH * 0.5, z: baseHalfWidth },
    material: coreMaterial,
    district
  });
  const upperHalfWidth = Math.max(5.5, baseHalfWidth * 0.78);
  const upperShaftH = totalHeight - midSplitY;
  if (upperShaftH > 4) {
    structures.push({
      id: `${idPrefix}_upper_shaft`,
      center: { x: x2, y: midSplitY + upperShaftH * 0.5, z: z2 },
      halfExtents: { x: upperHalfWidth, y: upperShaftH * 0.5, z: upperHalfWidth },
      material: coreMaterial,
      emissiveTrim: trimColor,
      district
    });
  }
  let tierIdx = 0;
  for (let y2 = podiumHeight + ledgeInterval; y2 <= totalHeight - 2; y2 += ledgeInterval) {
    const inUpper = y2 > midSplitY;
    const shaftHW = inUpper ? upperHalfWidth : baseHalfWidth;
    const lipOutset = tierIdx % 2 === 0 ? 2.2 : 1.5;
    structures.push({
      id: `${idPrefix}_ledge_${tierIdx}`,
      center: { x: x2, y: y2 - 0.4, z: z2 },
      halfExtents: { x: shaftHW + lipOutset, y: 0.4, z: shaftHW + lipOutset },
      material: "ledge_trim",
      emissiveTrim: tierIdx % 2 === 0 ? trimColor : void 0,
      district
    });
    const hvacSide = tierIdx % 4;
    const hvacOffset = shaftHW + lipOutset + 1.4;
    const hx = hvacSide === 0 ? x2 + hvacOffset : hvacSide === 1 ? x2 - hvacOffset : x2;
    const hz = hvacSide === 2 ? z2 + hvacOffset : hvacSide === 3 ? z2 - hvacOffset : z2;
    structures.push({
      id: `${idPrefix}_hvac_${tierIdx}`,
      center: { x: hx, y: y2 + 1.2, z: hz },
      halfExtents: { x: 2.2, y: 1.2, z: 2.2 },
      material: "industrial_grate",
      emissiveTrim: "amber",
      district
    });
    tierIdx += 1;
  }
  if (cfg.hasExteriorElevator) {
    structures.push({
      id: `${idPrefix}_elevator_spine`,
      center: { x: x2, y: totalHeight * 0.5, z: z2 + baseHalfWidth + 2.4 },
      halfExtents: { x: 2.8, y: totalHeight * 0.5, z: 1.8 },
      material: "obsidian_steel",
      emissiveTrim: "magenta",
      district
    });
  }
  structures.push({
    id: `${idPrefix}_rooftop_crown`,
    center: { x: x2, y: totalHeight - 0.6, z: z2 },
    halfExtents: { x: upperHalfWidth + 1.6, y: 0.6, z: upperHalfWidth + 1.6 },
    material: "obsidian_steel",
    emissiveTrim: trimColor,
    district
  });
  if (cfg.hasTurrets) {
    const cornerOffset = upperHalfWidth;
    const corners = [
      { cx: x2 - cornerOffset, cz: z2 - cornerOffset, tag: "nw" },
      { cx: x2 + cornerOffset, cz: z2 - cornerOffset, tag: "ne" },
      { cx: x2 - cornerOffset, cz: z2 + cornerOffset, tag: "sw" },
      { cx: x2 + cornerOffset, cz: z2 + cornerOffset, tag: "se" }
    ];
    for (const c2 of corners) {
      structures.push({
        id: `${idPrefix}_turret_${c2.tag}`,
        center: { x: c2.cx, y: totalHeight + 1.4, z: c2.cz },
        halfExtents: { x: 1.8, y: 1.4, z: 1.8 },
        material: "obsidian_steel",
        emissiveTrim: "magenta",
        district
      });
    }
  }
}
