function getElevatedOrbSurfaces() {
  const surfaces = [];
  for (const s2 of buildNeoVeridiaSector01()) {
    if (s2.excludeOrbPlacement || s2.id.startsWith("perimeter_wall_") || s2.id === "ground_plaza_main") continue;
    const topY = s2.center.y + s2.halfExtents.y;
    if (topY >= 10 && topY <= 310 && s2.halfExtents.x >= 1.8 && s2.halfExtents.z >= 1.8) {
      surfaces.push({
        structureId: s2.id,
        district: s2.district || getDistrictForPosition(s2.center.x, s2.center.z),
        topY,
        centerX: s2.center.x,
        centerZ: s2.center.z,
        halfWidthX: s2.halfExtents.x,
        halfDepthZ: s2.halfExtents.z
      });
    }
  }
  return surfaces;
}
function findActiveThermalUpdraft(pos) {
  for (const u2 of getNeoVeridiaThermalUpdrafts()) {
    if (pos.y >= u2.baseY && pos.y <= u2.topY) {
      const dx = pos.x - u2.center.x;
      const dz = pos.z - u2.center.z;
      if (dx * dx + dz * dz <= u2.radius * u2.radius) {
        return u2;
      }
    }
  }
  return null;
}

