    if (this.isAiming) {
      desiredArm = CAMERA_ARM_AIM;
    } else if (speed3D > 8.5) {
      const speedFactor = Math.min(1, (speed3D - 8.5) / 14);
      desiredArm = CAMERA_ARM_DEFAULT + speedFactor * (CAMERA_ARM_SPRINT_MAX - CAMERA_ARM_DEFAULT);
    }
