  syndicate: { armor: 10777645, joint: 5255981, trim: 16751656, roughness: 0.72, metalness: 0.55 },
  resistance: { armor: 2111538, joint: 7623489, trim: 4714398, roughness: 0.8, metalness: 0.25 }
