function createProceduralGridTexture(bgColor, lineColor, emissiveWindows) {
  const canvas = document.createElement("canvas");
  canvas.width = 256;
  canvas.height = 256;
  const ctx = canvas.getContext("2d");
  if (ctx) {
    ctx.fillStyle = bgColor;
    ctx.fillRect(0, 0, 256, 256);
    ctx.strokeStyle = lineColor;
    ctx.lineWidth = 2;
    for (let i2 = 0; i2 <= 256; i2 += 32) {
      ctx.beginPath();
      ctx.moveTo(i2, 0);
      ctx.lineTo(i2, 256);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(0, i2);
      ctx.lineTo(256, i2);
      ctx.stroke();
    }
    if (emissiveWindows) {
      for (let gx = 4; gx < 256; gx += 32) {
        for (let gy = 6; gy < 256; gy += 32) {
          const lit = (gx * 13 + gy * 7) % 5 !== 0;
          ctx.fillStyle = lit ? "rgba(0, 230, 255, 0.42)" : "rgba(12, 24, 38, 0.85)";
          ctx.fillRect(gx, gy, 24, 20);
        }
      }
    }
  }
  const tex = new CanvasTexture(canvas);
  tex.wrapS = RepeatWrapping;
  tex.wrapT = RepeatWrapping;
  return tex;
}
