        omegaBountyEl.textContent = `ACTIVE HVT #${bounty.enemyId} | ${bounty.timeRemainingSec.toFixed(1)}s LEFT | WP ${bounty.waypointIndex + 1}/${bounty.totalWaypoints} (${d2.toFixed(0)}m away \u2022 HP ${bounty.hp}/${bounty.maxHp})`;
